    pages['polityka-prywatnosci.html'] = ('Polityka prywatności | Probatum', 'Polityka prywatności probatum.pl: administrator danych, cele przetwarzania i przysługujące Ci prawa.', POLITYKA_PRYWATNOSCI_CONTENT, 'cookies')
